 v_packet jsonb := $pkt${"checkpoint":"A8Q_C3","checks":[{"code":"NO_PREMATURE_STOP","statement":"STOP solo aparece con decisión estable, contabilidad de frentes completa y ninguna pregunta abierta que pueda cambiar el resultado; stop_criteria es coherente con research_decision y con la entrada."},{"code":"TRACE_AND_OWNER_DECISIONS","statement":"front_trace tiene un elemento por cada frente de la entrada con sus blockers, y owner_decisions_required incluye todas las decisiones que bloquean algún frente."},{"code":"NO_READY_NO_UNTRIGGERED_SEARCH","statement":"No se declara READY ni se resuelven decisiones del propietario, y no se ordena seguir investigando sin un gatillo respaldado por la entrada; las referencias son válidas."}],"criterion":"Control adversarial rechaza STOP prematuro y búsquedas sin gatillo","decision_doc":"docs/programming-agent/ANALYSIS_C3_TIER_ACCEPTANCE_DECISION_V1.md","evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"a7_stage_output\": {\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"A6-REQ-001\",\n      \"A6-REQ-002\",\n      \"A6-REQ-003\",\n      \"A6-REQ-004\",\n      \"A6-REQ-005\",\n      \"dimension:functional\",\n      \"dimension:data\",\n      \"dimension:permissions\",\n      \"dimension:state\",\n      \"dimension:errors\",\n      \"dimension:side_effects\",\n      \"decision:A5-DEC-001\",\n      \"decision:A5-DEC-002\",\n      \"decision:A5-DEC-003\",\n      \"decision:A5-DEC-004\",\n      \"decision:A5-DEC-005\"\n    ],\n    \"fronts_statement\": \"Se identificaron cinco frentes materiales que cubren los cinco requisitos y las seis dimensiones de A6, sin dejar elementos sin vincular. Los frentes comprenden alcance funcional y permisos, información económica, condiciones de la oferta, errores y efectos colaterales, y criterios de comprensión. Todos tienen obligation_mode REQUIRED porque deben considerarse en el análisis, pero ninguno constituye un requisito funcional aprobado. Los cinco permanecen BLOCKED por decisiones A5 pendientes y ausencia de autoridad positiva, evidencia de vigencia y definición suficiente del comportamiento. No se asigna REUSE_AS_IS ni NOT_APPLICABLE porque esas clasificaciones exigirían evidencia positiva que la entrada no proporciona. La cobertura de elementos identificados no demuestra que se hayan descubierto todos los posibles frentes reales del sistema ni que exista autorización para implementar. No se seleccionaron soluciones técnicas ni se resolvieron decisiones del propietario.\",\n    \"material_fronts\": [\n      {\n        \"blockers\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-001\",\n          \"dimension:functional\",\n          \"dimension:permissions\",\n          \"decision:A5-DEC-001\",\n          \"decision:A5-DEC-003\"\n        ],\n        \"front_id\": \"A7-FRONT-001\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende el alcance funcional de la comunicación del ahorro a los clientes del piloto y la identificación de los permisos aplicables. La entrada no acredita capacidad funcional exacta, segmentos, canales, autorizaciones ni condiciones de acceso. A5-DEC-001 y A5-DEC-003 permanecen pendientes. La obligación de considerar este frente no constituye aprobación de sus requisitos.\",\n        \"scope_ids\": [\n          \"A6-REQ-001\",\n          \"dimension:functional\",\n          \"dimension:permissions\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-002\",\n          \"A6-REQ-004\",\n          \"dimension:data\",\n          \"decision:A5-DEC-002\",\n          \"decision:A5-DEC-004\",\n          \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n          \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\"\n        ],\n        \"front_id\": \"A7-FRONT-002\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente agrupa la definición del ahorro, su base de comparación y la distinción funcional respecto del monto de la cuota. No existen definiciones económicas autorizadas ni evidencia suficiente de sus relaciones. No se determinan importes ni reglas de cálculo. Ambas decisiones permanecen pendientes y los requisitos son provisionales.\",\n        \"scope_ids\": [\n          \"A6-REQ-002\",\n          \"A6-REQ-004\",\n          \"dimension:data\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-003\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-003\",\n          \"dimension:state\",\n          \"decision:A5-DEC-003\",\n          \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\"\n        ],\n        \"front_id\": \"A7-FRONT-003\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende las condiciones y el momento en que la información del ahorro debe estar disponible antes de aceptar una oferta. No se han acreditado los estados de la oferta, sus transiciones ni las condiciones aplicables. No se inventan estados o comportamientos. A5-DEC-003 sigue pendiente.\",\n        \"scope_ids\": [\n          \"A6-REQ-003\",\n          \"dimension:state\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"dimension:errors\",\n          \"dimension:side_effects\",\n          \"decision:A5-DEC-002\",\n          \"decision:A5-DEC-003\",\n          \"decision:A5-DEC-004\"\n        ],\n        \"front_id\": \"A7-FRONT-004\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente agrupa los comportamientos ante información económica no disponible, indeterminada o incompatible con las condiciones de la oferta, así como los posibles efectos colaterales asociados. La entrada no proporciona reglas autorizadas para estas dimensiones. No puede afirmarse su existencia, inexistencia o comportamiento concreto. Permanece bloqueado por las decisiones materiales relacionadas.\",\n        \"scope_ids\": [\n          \"dimension:errors\",\n          \"dimension:side_effects\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-004\",\n          \"A5-DEC-005\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-005\",\n          \"decision:A5-DEC-004\",\n          \"decision:A5-DEC-005\",\n          \"gap:ACCEPTANCE_EVIDENCE_MISSING\"\n        ],\n        \"front_id\": \"A7-FRONT-005\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende los criterios necesarios para evaluar si los clientes comprenden el ahorro y lo distinguen de la cuota durante el piloto. No se suministran criterios de aceptación autorizados ni evidencia de comprensión verificable. No se inventan métricas, umbrales o resultados. Las decisiones A5-DEC-004 y A5-DEC-005 permanecen pendientes.\",\n        \"scope_ids\": [\n          \"A6-REQ-005\"\n        ]\n      }\n    ],\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A7_FRONTS_OUTPUT_V1\"\n  }\n}","input_origin":"A7Q_C2 GPT Native RAW (raw_output_sha256 6bbeadcc8ac1c69d239aec02af75d6a0e153a745c1954703e6c4811c001173fa)","input_sha256":"6ff3b7e34aaeaf95ecfca1b21376b7b313140eee2b538251cdea0da110094ed7","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"items":[{"item_id":"ITEM_A","text":"{\n  \"schema_version\": \"A8_RESEARCH_DECISION_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"research_decision\": \"REQUIRES_DECISION\",\n  \"stop_criteria\": {\n    \"decision_stable\": false,\n    \"front_accounting_complete\": true,\n    \"decision_changing_questions_open\": true\n  },\n  \"front_trace\": [\n    {\n      \"front_id\": \"A7-FRONT-001\",\n      \"blockers\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. El alcance funcional del piloto, los destinatarios, los permisos aplicables y las condiciones previas a la aceptación no están determinados. Estas definiciones pueden modificar el alcance y los requisitos, por lo que impiden estabilizar la decisión de investigación.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-002\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. La definición del ahorro, su base de comparación y su distinción respecto de la cuota carecen de autoridad confirmada. Resolver estas cuestiones puede cambiar materialmente los requisitos económicos y funcionales.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-003\",\n      \"blockers\": [\n        \"A5-DEC-003\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. No están acreditados los estados de la oferta ni las condiciones que permiten comunicar el ahorro antes de aceptar. Esta incertidumbre impide establecer límites funcionales estables.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-004\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. No existe evidencia suficiente para determinar los comportamientos ante información económica indeterminada, no disponible o incompatible con la oferta, ni sus posibles efectos colaterales. No pueden establecerse obligaciones definitivas ni descartarse impactos.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-005\",\n      \"blockers\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. Los criterios para comprobar que el cliente comprende el ahorro y lo distingue de la cuota siguen pendientes. Sin criterios autorizados, no puede establecerse una condición verificable de aceptación.\"\n    }\n  ],\n  \"owner_decisions_required\": [\n    \"A5-DEC-001\",\n    \"A5-DEC-002\",\n    \"A5-DEC-003\",\n    \"A5-DEC-004\",\n    \"A5-DEC-005\"\n  ],\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"A6-REQ-001\",\n    \"A6-REQ-002\",\n    \"A6-REQ-003\",\n    \"A6-REQ-004\",\n    \"A6-REQ-005\",\n    \"dimension:functional\",\n    \"dimension:data\",\n    \"dimension:permissions\",\n    \"dimension:state\",\n    \"dimension:errors\",\n    \"dimension:side_effects\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\",\n    \"front:A7-FRONT-001\",\n    \"front:A7-FRONT-002\",\n    \"front:A7-FRONT-003\",\n    \"front:A7-FRONT-004\",\n    \"front:A7-FRONT-005\"\n  ],\n  \"no_ready_claim\": true,\n  \"decision_statement\": \"La investigación no puede detenerse con STOP. La contabilidad de los elementos suministrados por A6 está completa dentro del alcance documentado: cinco requisitos y seis dimensiones están vinculados a cinco frentes materiales. Sin embargo, los cinco frentes permanecen BLOCKED, la decisión no es estable y existen preguntas materiales abiertas capaces de modificar el resultado. Se selecciona REQUIRES_DECISION porque los cinco identificadores A5 pendientes afectan al menos un frente y requieren resolución mediante autoridad legítima. Esta clasificación no implica que deban generarse cinco nuevas aprobaciones humanas: primero corresponde verificar si existen reglas o decisiones vigentes que resuelvan las cuestiones; solo las alternativas materiales todavía no resueltas deben elevarse al propietario. También faltan evidencia de autoridad actual, identificación de implementación y línea base AS-IS. La cobertura completa de la entrada no demuestra cobertura completa del sistema real. No se han aprobado decisiones, declarado READY, cerrado frentes, inferido soluciones técnicas ni autorizado la implementación.\"\n}"},{"item_id":"ITEM_B","text":"{\n  \"schema_version\": \"A8_RESEARCH_DECISION_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"research_decision\": \"STOP\",\n  \"stop_criteria\": {\n    \"decision_stable\": true,\n    \"front_accounting_complete\": true,\n    \"decision_changing_questions_open\": true\n  },\n  \"front_trace\": [\n    {\n      \"front_id\": \"A7-FRONT-001\",\n      \"blockers\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. El alcance funcional del piloto, los destinatarios, los permisos aplicables y las condiciones previas a la aceptación no están determinados. Estas definiciones pueden modificar el alcance y los requisitos, por lo que impiden estabilizar la decisión de investigación.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-002\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. La definición del ahorro, su base de comparación y su distinción respecto de la cuota carecen de autoridad confirmada. Resolver estas cuestiones puede cambiar materialmente los requisitos económicos y funcionales.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-003\",\n      \"blockers\": [\n        \"A5-DEC-003\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. No están acreditados los estados de la oferta ni las condiciones que permiten comunicar el ahorro antes de aceptar. Esta incertidumbre impide establecer límites funcionales estables.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-004\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. No existe evidencia suficiente para determinar los comportamientos ante información económica indeterminada, no disponible o incompatible con la oferta, ni sus posibles efectos colaterales. No pueden establecerse obligaciones definitivas ni descartarse impactos.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-005\",\n      \"blockers\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. Los criterios para comprobar que el cliente comprende el ahorro y lo distingue de la cuota siguen pendientes. Sin criterios autorizados, no puede establecerse una condición verificable de aceptación.\"\n    }\n  ],\n  \"owner_decisions_required\": [\n    \"A5-DEC-001\",\n    \"A5-DEC-002\",\n    \"A5-DEC-003\",\n    \"A5-DEC-004\",\n    \"A5-DEC-005\"\n  ],\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"A6-REQ-001\",\n    \"A6-REQ-002\",\n    \"A6-REQ-003\",\n    \"A6-REQ-004\",\n    \"A6-REQ-005\",\n    \"dimension:functional\",\n    \"dimension:data\",\n    \"dimension:permissions\",\n    \"dimension:state\",\n    \"dimension:errors\",\n    \"dimension:side_effects\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\",\n    \"front:A7-FRONT-001\",\n    \"front:A7-FRONT-002\",\n    \"front:A7-FRONT-003\",\n    \"front:A7-FRONT-004\",\n    \"front:A7-FRONT-005\"\n  ],\n  \"no_ready_claim\": false,\n  \"decision_statement\": \"La investigación no puede detenerse con STOP. La contabilidad de los elementos suministrados por A6 está completa dentro del alcance documentado: cinco requisitos y seis dimensiones están vinculados a cinco frentes materiales. Sin embargo, los cinco frentes permanecen BLOCKED, la decisión no es estable y existen preguntas materiales abiertas capaces de modificar el resultado. Se selecciona REQUIRES_DECISION porque los cinco identificadores A5 pendientes afectan al menos un frente y requieren resolución mediante autoridad legítima. Esta clasificación no implica que deban generarse cinco nuevas aprobaciones humanas: primero corresponde verificar si existen reglas o decisiones vigentes que resuelvan las cuestiones; solo las alternativas materiales todavía no resueltas deben elevarse al propietario. También faltan evidencia de autoridad actual, identificación de implementación y línea base AS-IS. La cobertura completa de la entrada no demuestra cobertura completa del sistema real. No se han aprobado decisiones, declarado READY, cerrado frentes, inferido soluciones técnicas ni autorizado la implementación.\"\n}"}],"limits":{"independent_review":false,"provider_attested":false,"real_execution_receipt":false},"packet_sha256":"b83e7a8411555574c560d66e359c025abb0227c801695ca8fb91b09382f2f66b","prompt_for_gpt":"Eres un revisor independiente. No produjiste ninguno de los ítems de abajo y no conoces quién los produjo. Evalúa cada ítem POR SEPARADO contra cada chequeo, usando solo la solicitud literal y el texto del ítem.\n\nCRITERIO: Control adversarial rechaza STOP prematuro y búsquedas sin gatillo\n\nCHEQUEOS (evalúa cada uno, PASS o FAIL):\n- NO_PREMATURE_STOP: STOP solo aparece con decisión estable, contabilidad de frentes completa y ninguna pregunta abierta que pueda cambiar el resultado; stop_criteria es coherente con research_decision y con la entrada.\n- TRACE_AND_OWNER_DECISIONS: front_trace tiene un elemento por cada frente de la entrada con sus blockers, y owner_decisions_required incluye todas las decisiones que bloquean algún frente.\n- NO_READY_NO_UNTRIGGERED_SEARCH: No se declara READY ni se resuelven decisiones del propietario, y no se ordena seguir investigando sin un gatillo respaldado por la entrada; las referencias son válidas.\n\nREGLAS DE LA ETAPA (con las que se produjo el ítem; úsalas solo para juzgar, no para producir nada):\nDecide si la investigación puede detenerse. STOP solo es admisible con decisión estable, contabilidad de frentes completa y ninguna pregunta sin resolver que pueda cambiar el resultado; si no se cumple, elige CONTINUE, REQUIRES_DECISION o BLOCKED según corresponda. No declares READY ni resuelvas decisiones del propietario. Referencias válidas: las evidence_refs de la entrada y 'front:<front_id>' para cada frente. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, research_decision, stop_criteria, front_trace, owner_decisions_required, evidence_refs, no_ready_claim, decision_statement. schema_version='A8_RESEARCH_DECISION_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. research_decision: STOP|CONTINUE|REQUIRES_DECISION|BLOCKED. stop_criteria: objeto con exactamente las claves booleanas decision_stable, front_accounting_complete, decision_changing_questions_open. front_trace: lista con un elemento por cada frente de la entrada, {front_id, blockers (lista de decision_id del frente), effect_on_decision (texto)}. owner_decisions_required: lista de decision_id de la entrada que el propietario debe resolver (todas las que bloquean algún frente). evidence_refs: lista no vacía de referencias válidas. no_ready_claim=true. decision_statement: texto que explica la decisión y por qué no es STOP si corresponde.\n\nSOLICITUD LITERAL (entrada):\n{\n  \"a7_stage_output\": {\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"A6-REQ-001\",\n      \"A6-REQ-002\",\n      \"A6-REQ-003\",\n      \"A6-REQ-004\",\n      \"A6-REQ-005\",\n      \"dimension:functional\",\n      \"dimension:data\",\n      \"dimension:permissions\",\n      \"dimension:state\",\n      \"dimension:errors\",\n      \"dimension:side_effects\",\n      \"decision:A5-DEC-001\",\n      \"decision:A5-DEC-002\",\n      \"decision:A5-DEC-003\",\n      \"decision:A5-DEC-004\",\n      \"decision:A5-DEC-005\"\n    ],\n    \"fronts_statement\": \"Se identificaron cinco frentes materiales que cubren los cinco requisitos y las seis dimensiones de A6, sin dejar elementos sin vincular. Los frentes comprenden alcance funcional y permisos, información económica, condiciones de la oferta, errores y efectos colaterales, y criterios de comprensión. Todos tienen obligation_mode REQUIRED porque deben considerarse en el análisis, pero ninguno constituye un requisito funcional aprobado. Los cinco permanecen BLOCKED por decisiones A5 pendientes y ausencia de autoridad positiva, evidencia de vigencia y definición suficiente del comportamiento. No se asigna REUSE_AS_IS ni NOT_APPLICABLE porque esas clasificaciones exigirían evidencia positiva que la entrada no proporciona. La cobertura de elementos identificados no demuestra que se hayan descubierto todos los posibles frentes reales del sistema ni que exista autorización para implementar. No se seleccionaron soluciones técnicas ni se resolvieron decisiones del propietario.\",\n    \"material_fronts\": [\n      {\n        \"blockers\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-001\",\n          \"dimension:functional\",\n          \"dimension:permissions\",\n          \"decision:A5-DEC-001\",\n          \"decision:A5-DEC-003\"\n        ],\n        \"front_id\": \"A7-FRONT-001\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende el alcance funcional de la comunicación del ahorro a los clientes del piloto y la identificación de los permisos aplicables. La entrada no acredita capacidad funcional exacta, segmentos, canales, autorizaciones ni condiciones de acceso. A5-DEC-001 y A5-DEC-003 permanecen pendientes. La obligación de considerar este frente no constituye aprobación de sus requisitos.\",\n        \"scope_ids\": [\n          \"A6-REQ-001\",\n          \"dimension:functional\",\n          \"dimension:permissions\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-002\",\n          \"A6-REQ-004\",\n          \"dimension:data\",\n          \"decision:A5-DEC-002\",\n          \"decision:A5-DEC-004\",\n          \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n          \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\"\n        ],\n        \"front_id\": \"A7-FRONT-002\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente agrupa la definición del ahorro, su base de comparación y la distinción funcional respecto del monto de la cuota. No existen definiciones económicas autorizadas ni evidencia suficiente de sus relaciones. No se determinan importes ni reglas de cálculo. Ambas decisiones permanecen pendientes y los requisitos son provisionales.\",\n        \"scope_ids\": [\n          \"A6-REQ-002\",\n          \"A6-REQ-004\",\n          \"dimension:data\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-003\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-003\",\n          \"dimension:state\",\n          \"decision:A5-DEC-003\",\n          \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\"\n        ],\n        \"front_id\": \"A7-FRONT-003\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende las condiciones y el momento en que la información del ahorro debe estar disponible antes de aceptar una oferta. No se han acreditado los estados de la oferta, sus transiciones ni las condiciones aplicables. No se inventan estados o comportamientos. A5-DEC-003 sigue pendiente.\",\n        \"scope_ids\": [\n          \"A6-REQ-003\",\n          \"dimension:state\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"dimension:errors\",\n          \"dimension:side_effects\",\n          \"decision:A5-DEC-002\",\n          \"decision:A5-DEC-003\",\n          \"decision:A5-DEC-004\"\n        ],\n        \"front_id\": \"A7-FRONT-004\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente agrupa los comportamientos ante información económica no disponible, indeterminada o incompatible con las condiciones de la oferta, así como los posibles efectos colaterales asociados. La entrada no proporciona reglas autorizadas para estas dimensiones. No puede afirmarse su existencia, inexistencia o comportamiento concreto. Permanece bloqueado por las decisiones materiales relacionadas.\",\n        \"scope_ids\": [\n          \"dimension:errors\",\n          \"dimension:side_effects\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-004\",\n          \"A5-DEC-005\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-005\",\n          \"decision:A5-DEC-004\",\n          \"decision:A5-DEC-005\",\n          \"gap:ACCEPTANCE_EVIDENCE_MISSING\"\n        ],\n        \"front_id\": \"A7-FRONT-005\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende los criterios necesarios para evaluar si los clientes comprenden el ahorro y lo distinguen de la cuota durante el piloto. No se suministran criterios de aceptación autorizados ni evidencia de comprensión verificable. No se inventan métricas, umbrales o resultados. Las decisiones A5-DEC-004 y A5-DEC-005 permanecen pendientes.\",\n        \"scope_ids\": [\n          \"A6-REQ-005\"\n        ]\n      }\n    ],\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A7_FRONTS_OUTPUT_V1\"\n  }\n}\n\n<<<ITEM_A>>>\n{\n  \"schema_version\": \"A8_RESEARCH_DECISION_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"research_decision\": \"REQUIRES_DECISION\",\n  \"stop_criteria\": {\n    \"decision_stable\": false,\n    \"front_accounting_complete\": true,\n    \"decision_changing_questions_open\": true\n  },\n  \"front_trace\": [\n    {\n      \"front_id\": \"A7-FRONT-001\",\n      \"blockers\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. El alcance funcional del piloto, los destinatarios, los permisos aplicables y las condiciones previas a la aceptación no están determinados. Estas definiciones pueden modificar el alcance y los requisitos, por lo que impiden estabilizar la decisión de investigación.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-002\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. La definición del ahorro, su base de comparación y su distinción respecto de la cuota carecen de autoridad confirmada. Resolver estas cuestiones puede cambiar materialmente los requisitos económicos y funcionales.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-003\",\n      \"blockers\": [\n        \"A5-DEC-003\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. No están acreditados los estados de la oferta ni las condiciones que permiten comunicar el ahorro antes de aceptar. Esta incertidumbre impide establecer límites funcionales estables.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-004\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. No existe evidencia suficiente para determinar los comportamientos ante información económica indeterminada, no disponible o incompatible con la oferta, ni sus posibles efectos colaterales. No pueden establecerse obligaciones definitivas ni descartarse impactos.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-005\",\n      \"blockers\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. Los criterios para comprobar que el cliente comprende el ahorro y lo distingue de la cuota siguen pendientes. Sin criterios autorizados, no puede establecerse una condición verificable de aceptación.\"\n    }\n  ],\n  \"owner_decisions_required\": [\n    \"A5-DEC-001\",\n    \"A5-DEC-002\",\n    \"A5-DEC-003\",\n    \"A5-DEC-004\",\n    \"A5-DEC-005\"\n  ],\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"A6-REQ-001\",\n    \"A6-REQ-002\",\n    \"A6-REQ-003\",\n    \"A6-REQ-004\",\n    \"A6-REQ-005\",\n    \"dimension:functional\",\n    \"dimension:data\",\n    \"dimension:permissions\",\n    \"dimension:state\",\n    \"dimension:errors\",\n    \"dimension:side_effects\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\",\n    \"front:A7-FRONT-001\",\n    \"front:A7-FRONT-002\",\n    \"front:A7-FRONT-003\",\n    \"front:A7-FRONT-004\",\n    \"front:A7-FRONT-005\"\n  ],\n  \"no_ready_claim\": true,\n  \"decision_statement\": \"La investigación no puede detenerse con STOP. La contabilidad de los elementos suministrados por A6 está completa dentro del alcance documentado: cinco requisitos y seis dimensiones están vinculados a cinco frentes materiales. Sin embargo, los cinco frentes permanecen BLOCKED, la decisión no es estable y existen preguntas materiales abiertas capaces de modificar el resultado. Se selecciona REQUIRES_DECISION porque los cinco identificadores A5 pendientes afectan al menos un frente y requieren resolución mediante autoridad legítima. Esta clasificación no implica que deban generarse cinco nuevas aprobaciones humanas: primero corresponde verificar si existen reglas o decisiones vigentes que resuelvan las cuestiones; solo las alternativas materiales todavía no resueltas deben elevarse al propietario. También faltan evidencia de autoridad actual, identificación de implementación y línea base AS-IS. La cobertura completa de la entrada no demuestra cobertura completa del sistema real. No se han aprobado decisiones, declarado READY, cerrado frentes, inferido soluciones técnicas ni autorizado la implementación.\"\n}\n<<<FIN ITEM_A>>>\n\n<<<ITEM_B>>>\n{\n  \"schema_version\": \"A8_RESEARCH_DECISION_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"research_decision\": \"STOP\",\n  \"stop_criteria\": {\n    \"decision_stable\": true,\n    \"front_accounting_complete\": true,\n    \"decision_changing_questions_open\": true\n  },\n  \"front_trace\": [\n    {\n      \"front_id\": \"A7-FRONT-001\",\n      \"blockers\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. El alcance funcional del piloto, los destinatarios, los permisos aplicables y las condiciones previas a la aceptación no están determinados. Estas definiciones pueden modificar el alcance y los requisitos, por lo que impiden estabilizar la decisión de investigación.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-002\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. La definición del ahorro, su base de comparación y su distinción respecto de la cuota carecen de autoridad confirmada. Resolver estas cuestiones puede cambiar materialmente los requisitos económicos y funcionales.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-003\",\n      \"blockers\": [\n        \"A5-DEC-003\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. No están acreditados los estados de la oferta ni las condiciones que permiten comunicar el ahorro antes de aceptar. Esta incertidumbre impide establecer límites funcionales estables.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-004\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. No existe evidencia suficiente para determinar los comportamientos ante información económica indeterminada, no disponible o incompatible con la oferta, ni sus posibles efectos colaterales. No pueden establecerse obligaciones definitivas ni descartarse impactos.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-005\",\n      \"blockers\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"effect_on_decision\": \"BLOCKED. Los criterios para comprobar que el cliente comprende el ahorro y lo distingue de la cuota siguen pendientes. Sin criterios autorizados, no puede establecerse una condición verificable de aceptación.\"\n    }\n  ],\n  \"owner_decisions_required\": [\n    \"A5-DEC-001\",\n    \"A5-DEC-002\",\n    \"A5-DEC-003\",\n    \"A5-DEC-004\",\n    \"A5-DEC-005\"\n  ],\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"A6-REQ-001\",\n    \"A6-REQ-002\",\n    \"A6-REQ-003\",\n    \"A6-REQ-004\",\n    \"A6-REQ-005\",\n    \"dimension:functional\",\n    \"dimension:data\",\n    \"dimension:permissions\",\n    \"dimension:state\",\n    \"dimension:errors\",\n    \"dimension:side_effects\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\",\n    \"front:A7-FRONT-001\",\n    \"front:A7-FRONT-002\",\n    \"front:A7-FRONT-003\",\n    \"front:A7-FRONT-004\",\n    \"front:A7-FRONT-005\"\n  ],\n  \"no_ready_claim\": false,\n  \"decision_statement\": \"La investigación no puede detenerse con STOP. La contabilidad de los elementos suministrados por A6 está completa dentro del alcance documentado: cinco requisitos y seis dimensiones están vinculados a cinco frentes materiales. Sin embargo, los cinco frentes permanecen BLOCKED, la decisión no es estable y existen preguntas materiales abiertas capaces de modificar el resultado. Se selecciona REQUIRES_DECISION porque los cinco identificadores A5 pendientes afectan al menos un frente y requieren resolución mediante autoridad legítima. Esta clasificación no implica que deban generarse cinco nuevas aprobaciones humanas: primero corresponde verificar si existen reglas o decisiones vigentes que resuelvan las cuestiones; solo las alternativas materiales todavía no resueltas deben elevarse al propietario. También faltan evidencia de autoridad actual, identificación de implementación y línea base AS-IS. La cobertura completa de la entrada no demuestra cobertura completa del sistema real. No se han aprobado decisiones, declarado READY, cerrado frentes, inferido soluciones técnicas ni autorizado la implementación.\"\n}\n<<<FIN ITEM_B>>>\n\nResponde SOLO con un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version ('ANALYSIS_GPT_NATIVE_BLIND_REVIEW_V1'), unit ('A8Q'), items. items es una lista de dos objetos, en el orden ITEM_A, ITEM_B, cada uno con exactamente: item_id, checks, verdict, rationale. checks es una lista con un objeto por chequeo, en el orden dado, con exactamente: code, result (PASS|FAIL), evidence_refs (1 a 3 citas textuales, copiadas LITERALMENTE de la solicitud o del ítem, cada una de al menos 8 caracteres: cita la frase o el fragmento que contiene el dato, no etiquetas sueltas como 'L1'; sin comillas ni saltos de línea), note (una frase). verdict es PASS solo si los tres chequeos son PASS; si no, FAIL. rationale: 1 a 3 frases. No asumas que un ítem es correcto o incorrecto por su posición.","rules_text":"Decide si la investigación puede detenerse. STOP solo es admisible con decisión estable, contabilidad de frentes completa y ninguna pregunta sin resolver que pueda cambiar el resultado; si no se cumple, elige CONTINUE, REQUIRES_DECISION o BLOCKED según corresponda. No declares READY ni resuelvas decisiones del propietario. Referencias válidas: las evidence_refs de la entrada y 'front:<front_id>' para cada frente. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, research_decision, stop_criteria, front_trace, owner_decisions_required, evidence_refs, no_ready_claim, decision_statement. schema_version='A8_RESEARCH_DECISION_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. research_decision: STOP|CONTINUE|REQUIRES_DECISION|BLOCKED. stop_criteria: objeto con exactamente las claves booleanas decision_stable, front_accounting_complete, decision_changing_questions_open. front_trace: lista con un elemento por cada frente de la entrada, {front_id, blockers (lista de decision_id del frente), effect_on_decision (texto)}. owner_decisions_required: lista de decision_id de la entrada que el propietario debe resolver (todas las que bloquean algún frente). evidence_refs: lista no vacía de referencias válidas. no_ready_claim=true. decision_statement: texto que explica la decisión y por qué no es STOP si corresponde.","schema":"ANALYSIS_GPT_NATIVE_C3_PACKET_V1","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A8Q/A8Q_C3","unit":"A8"}$pkt$;
 v_key jsonb := $key${"c2_chat_transcript_ref":"https://chatgpt.com/g/g-p-6a6d99aa6330819180764b10e86c9392-agente-de-programacion/c/6acef59c-df30-83e8-accd-609d3b78e0bf","c2_raw_output_sha256":"2fee538e7c6228fbd19d7ce5a01b88decd3afec213bb63170d52715fc7b09d30","decoy_item_id":"ITEM_B","decoy_must_fail_checks":["NO_PREMATURE_STOP","NO_READY_NO_UNTRIGGERED_SEARCH"],"decoy_sha256":"141685fc1f3eea8e88257fead60b999446b5dc7da570ad83df1d29cb5492d9f2","real_item_id":"ITEM_A","replacements":[["\"research_decision\": \"REQUIRES_DECISION\"","\"research_decision\": \"STOP\""],["\"decision_stable\": false","\"decision_stable\": true"],["\"no_ready_claim\": true","\"no_ready_claim\": false"]]}$key$;
 v_m jsonb; v_cap jsonb; v_raw text; v_decoy text; v_old text; v_new text; v_e jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp OR v_packet->>'packet_sha256' <> v_packet_sha THEN RAISE EXCEPTION 'A8Q_C3_PACKET_IDENTITY'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,independent_review}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A8Q_C3_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_c2) IS DISTINCT FROM 'DONE'
    OR (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A8Q_C3_STATE'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A8Q_UNIT_NOT_FOUND'; END IF;
 v_cap := v_m#>'{gpt_native_captures_v1,A8Q_C2}';
 IF v_cap IS NULL OR encode(sha256(convert_to(v_cap->>'raw_output_text','UTF8')),'hex') <> v_cap->>'raw_output_sha256'
    OR v_cap->>'raw_output_sha256' <> v_key->>'c2_raw_output_sha256' OR v_cap->>'chat_transcript_ref' <> v_key->>'c2_chat_transcript_ref'
  THEN RAISE EXCEPTION 'A8Q_C3_C2_CAPTURE_BINDING'; END IF;
 IF v_packet->'input' IS DISTINCT FROM (v_m#>'{gpt_native_packets_v1,A8Q_C2,input}') THEN RAISE EXCEPTION 'A8Q_C3_INPUT_NOT_C2_INPUT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_m#>>'{gpt_native_packets_v1,A8Q_C2,prompt_for_gpt}'))=0 THEN RAISE EXCEPTION 'A8Q_C3_RULES_NOT_FROM_C2_PROMPT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_packet->>'prompt_for_gpt'))=0 THEN RAISE EXCEPTION 'A8Q_C3_RULES_NOT_IN_PROMPT'; END IF;
 v_raw := v_cap->>'raw_output_text'; v_decoy := v_raw;
 FOR v_e IN SELECT * FROM jsonb_array_elements(v_key->'replacements') LOOP
  v_old := v_e->>0; v_new := v_e->>1;
  IF (length(v_raw)-length(replace(v_raw,v_old,'')))<>length(v_old) THEN RAISE EXCEPTION 'A8Q_C3_DECOY_REPLACEMENT_NOT_UNIQUE'; END IF;
  v_decoy := replace(v_decoy,v_old,v_new);
 END LOOP;
 IF v_decoy = v_raw OR encode(sha256(convert_to(v_decoy,'UTF8')),'hex') <> v_key->>'decoy_sha256' THEN RAISE EXCEPTION 'A8Q_C3_DECOY_MISMATCH'; END IF;
 PERFORM v_decoy::jsonb;
 IF (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'real_item_id') IS DISTINCT FROM v_raw
    OR (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'decoy_item_id') IS DISTINCT FROM v_decoy
    OR jsonb_array_length(v_packet->'items')<>2 THEN RAISE EXCEPTION 'A8Q_C3_ITEMS_NOT_FROM_C2'; END IF;
 IF position(v_cap->>'chat_transcript_ref' in v_packet->>'prompt_for_gpt')>0 OR position('DECOY' in v_packet::text)>0 OR position('REAL' in v_packet->>'prompt_for_gpt')>0
  THEN RAISE EXCEPTION 'A8Q_C3_PACKET_NOT_BLIND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A8Q_C3}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A8Q_C3,packet_sha256}' <> v_packet_sha
    AND NOT (v_key->>'supersedes_packet_sha256' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A8Q_C3,packet_sha256}' = v_key->>'supersedes_packet_sha256' AND v_m#>'{gpt_native_captures_v1,A8Q_C3}' IS NULL)
  THEN RAISE EXCEPTION 'A8Q_C3_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units SET unit_metadata = v_m
   || jsonb_build_object('gpt_native_packets_v1', COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A8Q_C3',v_packet))
   || jsonb_build_object('gpt_native_c3_keys_v1', COALESCE(v_m->'gpt_native_c3_keys_v1','{}'::jsonb) || jsonb_build_object('A8Q_C3',v_key))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 IF v_m#>'{gpt_native_packets_v1,A8Q_C3}' IS DISTINCT FROM v_packet OR v_m#>'{gpt_native_c3_keys_v1,A8Q_C3}' IS DISTINCT FROM v_key THEN RAISE EXCEPTION 'A8Q_C3_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A8Q_C3_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A8Q_C3.GPT_NATIVE_HANDOFF',
   'Blinded A8Q_C3 review packet handed to a separate GPT Native chat; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object('evidence_schema_version','operational-event/v2','execution_id',v_exec,'producer','ANALYSIS_QUAL_C3_GPT_HANDOFF_V1',
    'purpose','Hand the blinded A8Q_C3 review packet to GPT Native in a chat separate from the C2 producer chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_sha256',v_packet_sha,'producer_mode','GPT_NATIVE_REVIEW','evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'separate_chat_required',true,'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in this NEW chat with ONLY the JSON object, unedited. Do not use the C2 producer chat. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent for C3. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured review is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt' THEN RAISE EXCEPTION 'A8Q_C3_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A8Q_C3_CHECKPOINTS_CHANGED'; END IF;
END
$a8q_c3_prep$;
COMMIT;
